class Counter {
    num balance;
    kaam init(num initial) { this.balance = initial; }
    kaam deposit(num amount) { this.balance = amount; }
    num value() { return this.balance; }
}
class Main {
    static kaam main() {
        num initial = toNum(readLine());
        num amount = toNum(readLine());
        Counter counter = new Counter(initial);
        counter.deposit(amount);
        printLine(counter.value());
    }
}

